(() => {
 const median=a=>{const sorted=[...a].sort((a,b)=>a-b);return sorted[Math.floor(sorted.length/2)]};
 document.querySelectorAll('.benchmark-explorer').forEach(root=>{
  const output=root.dataset.sweep==='output',lengths=output?[8,16,32,64]:[64,128,256];
  const slider=root.querySelector('input'),select=root.querySelector('select');
  const field=output?'output_tokens':'input_tokens',fixed=output?'input_tokens':'output_tokens';
  const rows=benchmarkRuns.filter(r=>r[fixed]===(output?128:32));
  const options=root.querySelector('.length-options');
  lengths.forEach((n,i)=>{const b=document.createElement('button');b.type='button';b.textContent=n+' tokens';b.onclick=()=>{slider.value=i;render()};options.append(b)});
  function render(){
   const length=lengths[Number(slider.value)],selected=rows.filter(r=>r[field]===length),base=rows.filter(r=>r[field]===lengths[0]);
   const time=median(selected.map(r=>r.latency_s)),speed=median(selected.map(r=>r.output_tokens_per_s));
   slider.setAttribute('aria-valuetext',length+' tokens');
   [...options.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===Number(slider.value))));
   root.querySelector('.bench-readout').innerHTML=`<div><strong>${time.toFixed(2)} s</strong><span>Median generation time</span></div><div><strong>${speed.toFixed(2)} tokens/s</strong><span>Median throughput</span></div>`;
   const metric=select.value,max=metric==='latency_s'?12:12,unit=metric==='latency_s'?'seconds':'tokens / second';
   let svg=`<svg viewBox="0 0 600 ${100+lengths.length*70}" role="img" aria-label="All measured ${output?'output':'prompt'} lengths, ${unit}. Selected length ${length} tokens.">`;
   for(let t=0;t<=max;t+=3){const x=100+t/max*465;svg+=`<path d="M${x} 35V${65+lengths.length*70}" stroke="#d7d2c6"/><text x="${x}" y="23" text-anchor="middle">${t}</text>`}
   lengths.forEach((n,i)=>{const values=rows.filter(r=>r[field]===n).map(r=>r[metric]),y=65+i*70,active=n===length,color=active?'#195477':'#77776d';if(active)svg+=`<rect x="0" y="${y-23}" width="590" height="49" fill="#195477" fill-opacity=".06"/>`;
    svg+=`<text x="0" y="${y+6}" fill="${color}">${n} tokens</text>`;
    values.forEach((v,j)=>{svg+=`<circle cx="${100+v/max*465}" cy="${y+(j-2)*6}" r="${active?6:4}" fill="${color}"><title>${v.toFixed(3)} ${unit}</title></circle>`});
    const x=100+median(values)/max*465;svg+=`<path d="M${x} ${y-22}v44" stroke="${active?'#b85524':color}" stroke-width="3"/>`;
   });svg+=`<text x="330" y="${95+lengths.length*70}" text-anchor="middle">${unit}</text></svg>`;
   root.querySelector('.bench-plot').innerHTML=svg;
   const ratio=time/median(base.map(r=>r.latency_s));
   root.querySelector('.bench-comparison').textContent=length===lengths[0]?`Start here: ${length} ${output?'output':'prompt'} tokens is the comparison baseline.`:`${(length/lengths[0]).toFixed(0)}× the ${output?'output':'prompt'} tokens took ${ratio.toFixed(2)}× the median generation time. The measured range at this length was ${Math.min(...selected.map(r=>r.latency_s)).toFixed(2)}–${Math.max(...selected.map(r=>r.latency_s)).toFixed(2)} seconds.`;
   root.querySelector('.bench-table').innerHTML='<table><thead><tr><th>Run</th><th>Seconds</th><th>Tokens/s</th></tr></thead><tbody>'+[...selected].sort((a,b)=>a.repeat-b.repeat).map(r=>`<tr><td>${r.repeat+1}</td><td>${r.latency_s.toFixed(3)}</td><td>${r.output_tokens_per_s.toFixed(3)}</td></tr>`).join('')+'</tbody></table>';
  }
  slider.addEventListener('input',render);select.addEventListener('change',render);render();
 });
})();
